# Generated from assets/study-review by dev/sync-local.py --manifest-only.
FRONT = '<article class="sr-card" data-side="front">\n  <div class="sr-eyebrow">语境回忆 · 先想意思，再看答案</div>\n  <h1 class="sr-question">{{Word}}</h1>\n  <template class="sr-tags">{{Tags}}</template>\n  {{#Sentence}}<section class="sr-context" hidden><div class="sr-label">原句</div><div class="sr-sentence">{{Sentence}}</div></section>{{/Sentence}}\n  <p class="sr-hint">这个词或表达，在这句话里是什么意思？</p>\n</article>\n<script>\n(function () {\n  var cards = document.querySelectorAll(\'.sr-card[data-side="front"]\');\n  var card = cards[cards.length - 1];\n  if (!card || card.dataset.ready) return;\n  card.dataset.ready = \'true\';\n  var question = card.querySelector(\'.sr-question\');\n  var source = question.querySelector(\'[data-study-clip]\');\n  var context = card.querySelector(\'.sr-context\');\n  var heading = card.querySelector(\'.sr-eyebrow\');\n  if (!source) {\n    var tag = card.querySelector(\'.sr-tags\').content.textContent.match(/(?:^|\\s)study_kind::([a-z-]+)(?=\\s|$)/i);\n    var kind = tag ? tag[1].toLowerCase() : \'\';\n    if (kind) {\n      heading.textContent = kind === \'meaning\' ? \'回想词义\' : \'先作答，再看答案\';\n      card.querySelector(\'.sr-hint\').remove();\n    }\n    if (context) {\n      var sentence = context.querySelector(\'.sr-sentence\').textContent.replace(/\\s+/g, \'\');\n      var alreadyInQuestion = kind && sentence && question.textContent.replace(/\\s+/g, \'\').includes(sentence);\n      var standalone = /^(meaning|cloze|produce|form-recognize|form-produce|make-sentence)$/.test(kind);\n      if (standalone || alreadyInQuestion) context.remove();\n      else context.hidden = false;\n    }\n    return;\n  }\n  if (context) context.remove();\n  card.querySelector(\'.sr-hint\').remove();\n  var filename = source.getAttribute(\'data-study-clip\');\n  if (!filename) {\n    heading.textContent = \'这张卡缺少原声，可以先翻面看原句。\';\n    return;\n  }\n  heading.textContent = \'先听原声，再看答案\';\n  var player = document.createElement(\'audio\');\n  player.controls = true;\n  player.preload = \'none\';\n  player.src = encodeURIComponent(filename);\n  player.setAttribute(\'aria-label\', \'播放这张卡的原声\');\n  card.appendChild(player);\n})();\n</script>\n'
BACK = '<article class="sr-card" data-side="back">\n  <div class="sr-eyebrow">语境回忆 · 对照自己的理解</div>\n  <h1 class="sr-question">{{Word}}</h1>\n  {{#Sentence}}<section class="sr-context"><div class="sr-label">原句</div><div class="sr-sentence">{{Sentence}}</div></section>{{/Sentence}}\n  <section id="answer" class="sr-answer"><div class="sr-label">答案与用法</div><div class="sr-definition">{{Definition}}</div></section>\n  <details class="sr-dictionary" hidden><summary>词典原文与例句</summary><div class="sr-reference"></div></details>\n  <footer class="sr-source">{{Source}}<span class="sr-url-value" hidden>{{URL}}</span></footer>\n  {{#Audio}}<details class="sr-media"><summary>听发音</summary><div>{{Audio}}</div></details>{{/Audio}}\n  {{#Image}}<details class="sr-media"><summary>查看当时的画面</summary><div>{{Image}}</div></details>{{/Image}}\n</article>\n<script>\n(function () {\n  var cards = document.querySelectorAll(\'.sr-card[data-side="back"]\');\n  var card = cards[cards.length - 1];\n  if (!card || card.dataset.ready) return;\n  card.dataset.ready = \'true\';\n  var answer = card.querySelector(\'.sr-definition\');\n  var reference = card.querySelector(\'.sr-dictionary\');\n  // A quick dictionary card may contain the upstream full glossary. Keep it\n  // available without allowing it to bury the remembered sentence and answer.\n  if (answer && answer.querySelector(\'[data-sc-study-role], ol, ul\')) {\n    var gloss = answer.querySelector(\'[data-sc-study-role="meaning"]\');\n    var summary = gloss ? gloss.textContent.trim() : \'\';\n    var fragment = document.createDocumentFragment();\n    while (answer.firstChild) fragment.appendChild(answer.firstChild);\n    reference.querySelector(\'.sr-reference\').appendChild(fragment);\n    reference.hidden = false;\n    answer.textContent = summary || \'这张是快速词典卡。展开下方词典，对照原句回忆含义。\';\n    var source = document.createElement(\'div\');\n    source.className = \'sr-quick-note\';\n    source.textContent = \'词典释义 · 未自动按当前句消歧\';\n    answer.appendChild(source);\n  }\n  var urlText = card.querySelector(\'.sr-url-value\');\n  if (urlText && urlText.textContent.trim()) {\n    try {\n      var url = new URL(urlText.textContent.trim());\n      if ((url.protocol === \'https:\' || url.protocol === \'http:\') && !url.username && !url.password) {\n        var link = document.createElement(\'a\');\n        link.textContent = \'回原文\'; link.href = url.href;\n        link.target = \'_blank\'; link.rel = \'noopener noreferrer\';\n        card.querySelector(\'.sr-source\').appendChild(link);\n      }\n    } catch (_) { /* Invalid old URL remains data, never executable navigation. */ }\n  }\n})();\n</script>\n'
CSS = '/* Same seven fields and card identity; presentation only. */\n.card { margin:0; padding:24px; text-align:left; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; font-size:17px; line-height:1.7; color:#263247; background:#f6f7fb; }\n.sr-card { max-width:680px; margin:0 auto; }\n.sr-eyebrow { color:#68768d; font-size:11px; letter-spacing:.04em; margin-bottom:16px; }\n.sr-question { font-size:25px; font-weight:650; line-height:1.55; letter-spacing:-.02em; margin:0 0 20px; overflow-wrap:anywhere; }\n.sr-context { background:#fff; border:1px solid #e1e6ef; border-radius:10px; padding:14px 17px; margin-bottom:22px; }\n.sr-label { color:#657796; font-size:11px; font-weight:600; margin-bottom:6px; }\n.sr-sentence { font-size:17px; line-height:1.8; }\n.sr-hint { margin-top:22px; font-size:12px; color:#77839a; }\n.sr-card audio { max-width:100%; }\n.sr-answer { border-left:3px solid #5966a8; padding:3px 0 4px 16px; margin:0 0 20px; }\n.sr-definition { font-size:17px; line-height:1.8; overflow-wrap:anywhere; }\n.sr-quick-note { color:#7a8497; font-size:11px; margin-top:8px; }\n.sr-dictionary, .sr-media { border-top:1px solid #e1e6ef; padding:10px 0; margin-top:12px; font-size:13px; }\n.sr-dictionary[hidden] { display:none; }\n.sr-dictionary summary, .sr-media summary { color:#667895; cursor:pointer; }\n.sr-reference { padding-top:12px; font-size:14px; }\n.sr-reference ol { padding-left:20px; }\n.sr-source { color:#7b8598; font-size:11px; line-height:1.7; overflow-wrap:anywhere; }\n.sr-source a { color:#5064a7; text-decoration:none; margin:0 8px 0 0; }\n.sr-source a:hover { text-decoration:underline; }\n.sr-url-value { display:none; }\n.sr-media img { max-width:100%; height:auto; max-height:300px; object-fit:contain; }\n.sr-media>div { padding-top:10px; }\n.nightMode.card, .night_mode .card { color:#e7edf7; background:#182130; }\n.nightMode .sr-context, .night_mode .sr-context { background:#202c3d; border-color:#364258; }\n.nightMode .sr-label, .night_mode .sr-label { color:#aab9de; }\n.nightMode .sr-source, .night_mode .sr-source, .nightMode .sr-eyebrow { color:#a7b3c8; }\n@media(max-width:440px) { .card {padding:18px 15px;} .sr-question {font-size:22px;} .sr-sentence,.sr-definition{font-size:16px;} }\n'
